/* Copies what the Next.js site shares with web-v2, so both stay identical:
 *   web-v2/v2.css                  -> app/v2.css            (the whole look)
 *   web-v2/assets/brand/*, *.jpg/png -> public/assets/...    (logos, icons, about photos)
 *   web-v2/assets/data.js          -> lib/generated/demo-data.js (the demo catalogue and price maths, wrapped as a module)
 * Runs before `dev` and `build` (see package.json). The copies are generated files: edit the web-v2 originals instead. */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, '..');
const v2 = path.resolve(root, '..', 'web-v2');

function copy(from, to) {
  fs.mkdirSync(path.dirname(to), { recursive: true });
  fs.copyFileSync(from, to);
}

// 1. Styles. The Next layout imports app/v2.css; the brand tokens are served from public/.
copy(path.join(v2, 'v2.css'), path.join(root, 'app', 'v2.css'));

// 2. Static assets used by the pages.
const assetsIn = path.join(v2, 'assets');
for (const f of fs.readdirSync(path.join(assetsIn, 'brand'))) copy(path.join(assetsIn, 'brand', f), path.join(root, 'public', 'assets', 'brand', f));
for (const f of fs.readdirSync(assetsIn)) if (/\.(jpe?g|png|webp|svg)$/i.test(f)) copy(path.join(assetsIn, f), path.join(root, 'public', 'assets', f));

// 3. The demo catalogue. data.js is a browser script that reads window.__CATALOG and sets window.DOABNO_DATA.
// Wrapping it in a function with its own `window` and no `localStorage` lets the server run it once per catalogue.
const data = fs.readFileSync(path.join(assetsIn, 'data.js'), 'utf8');
const wrapped = '/* GENERATED by scripts/sync-v2.mjs from web-v2/assets/data.js. Do not edit. */\n/* eslint-disable */\n' +
  'export function buildData(catalog) {\n' +
  '  const window = { __CATALOG: catalog || null };\n' +
  '  const localStorage = undefined; // admin edits saved in a browser do not apply on the server\n' +
  data + '\n  return window.DOABNO_DATA;\n}\n';
fs.mkdirSync(path.join(root, 'lib', 'generated'), { recursive: true });
fs.writeFileSync(path.join(root, 'lib', 'generated', 'demo-data.js'), wrapped);

console.log('sync-v2: copied v2.css, assets and data.js from', v2);
